async function filesUnder(directory){
  const l=resolve(projectRoot,directory),entries=await readdir(l,{withFileTypes:true});
  const nested=await Promise.all(entries.map(async entry=>{
    const path=relative(projectRoot,resolve(l,entry.name)).replaceAll('\\','/');
    return entry.isDirectory()?filesUnder(path):[path];
  }));
  return nested.flat();
}
